package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.thaumaturgy.*;
import thaumcraft.aura.*;
import thaumcraft.crystals.*;
import thaumcraft.research.*;
@Mod.EventBusSubscriber(modid="thaumcraft")
public final class CanvasProbe {
 static final BlockPos P=new BlockPos(64008,160,8);static final UUID OWNER=UUID.fromString("4fefba0c-7432-4321-b3d1-72a7c7876501");static FocalEntity table;static ServerPlayer actor;static int ticks;static boolean done;
 static String mode(){return System.getProperty("thaumcraft.bookProbe","");}
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static ItemStack item(String name){return new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get(name).get());}
 static FocusProgram leaf(String medium,String effect){return new FocusProgram(medium,List.of(new FocusProgram.Effect(effect,1,1)));}
 public static FocusProgram graph(){return new FocusProgram("projectile",List.of(new FocusProgram.Effect("fire",1,1),new FocusProgram.Effect("air",2,1))).modifier("split_trajectory").withChild(0,leaf("bolt","break"));}
 static FocusProgram sequence(){return new FocusProgram("bolt",List.of()).withChild(0,leaf("touch","break"));}
 static void knowledge(ServerPlayer p){var s=KnowledgeState.EMPTY;for(var entry:ResearchCatalog.ENTRIES)s=s.stage(entry.key(),entry.stages().size()+1);check(KnowledgeStore.write(p,s),"Cannot prepare native research");}
 static int select(FocalMenu menu,ServerPlayer p,FocusProgram graph,List<Integer> address,int branch,int kind,int effect){var nodes=FocusCanvas.nodes(graph);for(int i=0;i<nodes.size();i++){var n=nodes.get(i);if(n.address().equals(address)&&n.branch()==branch&&n.kind()==kind&&(kind!=FocusCanvas.EFFECT||n.effect()==effect)){check(menu.clickMenuButton(p,FocusCanvas.FIRST_SELECT+i),"Selection rejected");return i;}}throw new AssertionError("Missing projected selection");}
 static void rules(ServerPlayer p,FocalEntity f){f.draft=graph();var m=new FocalMenu(71,p.getInventory(),f);var other=new FocalMenu(72,p.getInventory(),f);select(m,p,f.draft,List.of(),0,FocusCanvas.EFFECT,0);select(other,p,f.draft,List.of(),1,FocusCanvas.EFFECT,0);check(m.clickMenuButton(p,3)&&f.draft.effects().getFirst().power()==2&&f.draft.effects().get(1).power()==2,"Non-last effect edit changed the wrong effect");check(other.clickMenuButton(p,3)&&f.draft.branches().getFirst().effects().getFirst().power()==2&&m.value(10)==0,"Concurrent menus shared selection");check(m.clickMenuButton(p,88+FocusProgram.EFFECTS.indexOf("frost"))&&f.draft.effects().getFirst().kind().equals("frost"),"Direct palette did not replace selected effect");check(!m.clickMenuButton(p,127),"Out-of-range edit accepted");
  select(m,p,f.draft,List.of(),0,FocusCanvas.EFFECT,0);check(m.clickMenuButton(p,6)&&f.draft.effects().size()==1&&f.draft.effects().getFirst().kind().equals("air"),"Selected-effect deletion removed the wrong sibling");check(m.clickMenuButton(p,5)&&m.value(27)==1,"New effect was not selected");
  f.draft=leaf("bolt","fire");m=new FocalMenu(73,p.getInventory(),f);check(m.clickMenuButton(p,22)&&m.clickMenuButton(p,23)&&m.clickMenuButton(p,6)&&f.draft.effects().isEmpty(),"Cannot make a medium-only intermediate node");check(!m.clickMenuButton(p,24),"Deleting the only continuation created an empty terminal");check(m.clickMenuButton(p,88)&&!f.draft.effects().isEmpty(),"Palette could not populate an empty intermediate node");
  f.draft=leaf("touch","air");m=new FocalMenu(74,p.getInventory(),f);for(int i=0;i<7;i++)check(m.clickMenuButton(p,22),"Depth eight navigation rejected");var before=f.draft;check(!m.clickMenuButton(p,22)&&f.draft.equals(before),"Ninth level accepted");for(int i=0;i<7;i++)check(m.clickMenuButton(p,23),"Cannot return from deep node");
  f.draft=graph();select(m,p,f.draft,List.of(0),0,FocusCanvas.MEDIUM,-1);var root=new FocalMenu(75,p.getInventory(),f);select(root,p,f.draft,List.of(),0,FocusCanvas.MEDIUM,-1);check(root.clickMenuButton(p,24),"Could not delete continuation");m.broadcastChanges();check(m.value(25)==0,"Stale route did not safely return to root");thaumcraft.Thaumcraft.LOGGER.info("CANVAS65_SELECTION_RULES_OK: non-last effects, independent menus, palette, deletion, depth eight and stale routes");
 }
 static void execution(ServerPlayer p){var l=p.level();var q=P.south(4).above();l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());p.setYRot(0);p.setXRot(0);var focus=item("focus_3");focus.set(ThaumaturgyContent.PROGRAM.get(),sequence());var caster=item("caster_basic");caster.set(ThaumaturgyContent.FOCUS.get(),focus);p.setItemInHand(InteractionHand.MAIN_HAND,caster);AuraData.get(l).put(AuraCell.key(P.getX()>>4,P.getZ()>>4),new AuraCell(200,200,0));float before=AuraManager.get(l,P).vis();check(((CasterItem)caster.getItem()).use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Sequence refused native caster");check(l.getBlockState(q).isAir(),"Medium-only sequence did not execute its terminal break");check(Math.abs(before-AuraManager.get(l,P).vis()-sequence().vis())<.001,"Sequence charged vis more than once");thaumcraft.Thaumcraft.LOGGER.info("CANVAS65_SEQUENCE_CAST_OK: actual caster executes medium-only bolt to touch/break and pays aura once");}
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!mode().equals("canvas-write")&&!mode().equals("canvas-read"))return;e.getServer().tickRateManager().setFrozen(false);var l=e.getServer().overworld();for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)l.getChunk((P.getX()>>4)+x,z);l.setChunkForced(P.getX()>>4,P.getZ()>>4,true);actor=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"CanvasProof"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean overlay){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};new net.minecraft.server.network.ServerGamePacketListenerImpl(e.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),actor,net.minecraft.server.network.CommonListenerCookie.createInitial(actor.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,io.netty.channel.ChannelFutureListener listener){}};actor.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);actor.setPos(P.getX()+.5,P.getY(),P.getZ()-1.5);
  if(mode().equals("canvas-read")){table=(FocalEntity)l.getBlockEntity(P);check(table!=null&&table.working()&&table.draft.equals(sequence())&&table.remaining()>0&&table.remaining()<table.total(),"Saved paid sequence did not resume");for(int i=1;i<10;i++)check(table.inventory.getItem(i).isEmpty(),"Paid crystals reappeared on restart");return;}
  for(var q:BlockPos.betweenClosed(P.offset(-4,-1,-3),P.offset(4,4,10)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(P,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(P);knowledge(actor);rules(actor,table);execution(actor);table.draft=sequence();table.inventory.clearContent();table.inventory.setItem(0,item("focus_3"));int i=1;for(var entry:sequence().crystals().entrySet())table.inventory.setItem(i++,CrystalContent.essence(entry.getKey(),entry.getValue()));actor.experienceLevel=40;var knowledge=ResearchService.state(actor);KnowledgeStore.write(actor,knowledge.stage("FOCUSBOLT",0));check(!table.start(actor)&&actor.experienceLevel==40,"Missing research consumed XP");KnowledgeStore.write(actor,knowledge);check(table.start(actor)&&actor.experienceLevel==40-sequence().levels(),"Sequence craft payment failed");check(!new FocalMenu(76,actor.getInventory(),table).clickMenuButton(actor,80),"Crafting allowed graph mutation");AuraManager.addVis(l,P,1000);
 }
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(table==null||done||!mode().startsWith("canvas-"))return;if(++ticks>1200)throw new AssertionError("Native sequence job timeout");if(mode().equals("canvas-write")){if(table.remaining()==table.total())return;done=true;thaumcraft.Thaumcraft.LOGGER.info("CANVAS65_WRITE_OK: paid sequence saved in flight; edits locked");e.server().halt(false);}else if(mode().equals("canvas-read")&&!table.working()){check(table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get()).equals(sequence()),"Final focus changed saved sequence");done=true;thaumcraft.Thaumcraft.LOGGER.info("CANVAS65_RESTART_OK: sequence completed after second JVM without second payment");e.server().halt(false);}}
}
